head.script:
scwin.trigger1_onclick = function(e) {
    dataMap1.set("key1", "binding success");
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행 후 "setValue"버튼을 클릭한다.
    //1. Run the sample file and click the "setValue" button.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. 'binding success'값이 보여진다.(이전에는 값을 가져오지 못했음)
    //The 'binding success' value is displayed.(Previously, the value could not be retrieved)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'se___input').value == 'binding success'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 30-Jan-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
